// ===========================================================================
// SESSION 12 — WHAT CHANGED IN THE PROJECT
// ---------------------------------------------------------------------------
// Theme of this session: our first backend. We connect the app to Firebase
// and add sign-in: register / sign in with email + password, stay signed in
// after a restart, sign out. Each user also gets a document in Firestore
// (Users/{uid}).
//
// Files we actually changed (everything else is the same as session 11):
//   • firebase_options.dart          NEW. Generated by `flutterfire configure`.
//                                    Says WHICH Firebase project to talk to.
//   • models/user_model/
//       user_provider_model.dart     NEW. The user model, with fromMap() and,
//                                    new this time, toMap().
//   • services/firebase/
//       crud_firestore.dart          NEW. Our wrapper around Firestore:
//                                    setDocument() and getDocument().
//   • Controllers/provider_account.dart NEW. Sign in, register,
//                                    restoreSession, signOut, and the user's
//                                    Firestore document.
//   • Controllers/app_controllers.dart CHANGED: added accountProvider.
//   • Views/home_page.dart           CHANGED: a login form when signed out,
//                                    a small profile when signed in.
//   • main.dart (this file)          CHANGED: main() is async, starts
//                                    Firebase and restores the session
//                                    before runApp().
//
// New packages this session: firebase_core, firebase_auth, cloud_firestore.
// Setup steps (Firebase console + flutterfire configure): see the README.
//
// What we learned: what a backend is, connecting Firebase, Firebase
// Authentication (email/password), Firestore collections / documents /
// fields, toMap(), try/catch/finally, context.mounted, and a screen that
// switches on sign-in state.
// ===========================================================================

import 'package:firebase_core/firebase_core.dart'; // NEW
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import 'Controllers/app_controllers.dart';
import 'Views/TaskList_page.dart';
import 'Views/home_page.dart';
import 'firebase_options.dart'; // NEW: generated by flutterfire configure

// CHANGED: main() is now `async`, because we must WAIT for Firebase before
// using it.
void main() async {
  // NEW: needed whenever we `await` something before runApp().
  WidgetsFlutterBinding.ensureInitialized();

  // NEW: 1. connect to our Firebase project (settings from firebase_options).
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  debugPrint('Connected to Firebase: ${Firebase.app().options.projectId}');

  // NEW: 2. if someone was already signed in, load them BEFORE the first
  // frame, so a returning user never sees the login form flash.
  // appcontainer.read works here, before any widget exists.
  await appcontainer.read(accountProvider).restoreSession();

  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  // This widget is the root of your application.
  @override
  Widget build(BuildContext context) {
    return UncontrolledProviderScope(
      container: appcontainer,
      child: MaterialApp(
        debugShowCheckedModeBanner: false,
        // HomePage now shows the login form or the profile.
        home: const HomePage(),
        routes: {
          "/home": (context) => const HomePage(),
          "/tasks": (context) => const TaskListPage(),
        },
      ),
    );
  }
}
